ramify 1
// Presentation primitives shared by both feature views. `ui` keeps them out of
// the core owners, which carry no UI classification.
module shared-ui tagged [ui, browser]

// The badge and the props it is rendered with. `ui` is what keeps both out of
// the core owners; `browser` is this owner's promise that the badge's whole
// runtime is browser-safe, which is what lets the two feature views import it
// as a value.
expose-src StatusBadge, StatusBadgeProps from "status-badge.tsx" tagged [ui, browser] to parent

import type { ReactElement } from 'react';

import type { ReviewStatus } from '../../contracts/src/interfaces/vocabulary.js';

/**
 * The one presentation primitive both feature views render.
 *
 * It is deliberately tiny: a status and an optional label. Everything it needs
 * arrives as props, so the badge knows nothing about records, reviews, or the
 * protocol that produced either. Its styling is the application stylesheet's
 * plain `.status-badge` rules rather than a stylesheet of its own, which keeps
 * one badge looking the same wherever a feature places it.
 */

/** What the badge is rendered with. */
export interface StatusBadgeProps {
  status: ReviewStatus;
  label?: string;
}

/** The word each status reads as when the caller supplies no label. */
const defaultLabels: Record<ReviewStatus, string> = {
  passed: 'Passed',
  failed: 'Failed',
};

/**
 * One status, shown as a badge. `data-status` carries the status itself, so
 * both the stylesheet and a test can read it without matching on the label a
 * feature chose.
 */
export function StatusBadge({ status, label }: StatusBadgeProps): ReactElement {
  return (
    <span className="status-badge" data-status={status}>
      {label ?? defaultLabels[status]}
    </span>
  );
}

import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';

import { StatusBadge } from '../status-badge.js';

/**
 * The badge, checked as static markup.
 *
 * These tests run under Node: this owner's test area carries `ui` but never
 * `browser`, so a component written for the browser is exercised by rendering
 * it to a string rather than by mounting it in one.
 */

describe('StatusBadge', () => {
  it('reads a status back as its own word when no label is given', () => {
    expect(renderToStaticMarkup(<StatusBadge status="passed" />)).toContain('Passed');
    expect(renderToStaticMarkup(<StatusBadge status="failed" />)).toContain('Failed');
  });

  it('carries the status as an attribute whatever the label says', () => {
    const markup = renderToStaticMarkup(<StatusBadge status="failed" label="No revisions" />);

    expect(markup).toContain('data-status="failed"');
    expect(markup).toContain('No revisions');
    expect(markup).not.toContain('Failed');
  });
});

